          <div className="threshold-meter"><div><span>Reading</span><b>{Number(record.value).toFixed(2)} {unit}</b></div><div className="meter-track"><i style={{width:`${thresholdPosition}%`}}/><span style={{left:`${Math.max(2,Math.min(98,threshold/Math.max(threshold*1.5,Number(record.value)*1.15,0.01)*100))}%`}}/></div><div className="meter-labels"><span>0</span><span>Demo threshold {threshold} {unit}</span></div></div>
